// Select device variant (set by the makefile, default: ATSAMD21G18A)
// Revision B and D devices (e.g. ATSAMD21G17D) use the defines of the A devices.
#if   defined(__SAMD21E15A__) || defined(__SAMD21E15B__) || defined(__SAMD21E15D__)
  #define SAMD21E
  #define SAMD21_FLASH_KB   32
#elif defined(__SAMD21E16A__) || defined(__SAMD21E16B__) || defined(__SAMD21E16D__)
  #define SAMD21E
  #define SAMD21_FLASH_KB   64
#elif defined(__SAMD21E17A__) || defined(__SAMD21E17D__)
  #define SAMD21E
  #define SAMD21_FLASH_KB   128
#elif defined(__SAMD21E18A__)
  #define SAMD21E
  #define SAMD21_FLASH_KB   256
#elif defined(__SAMD21G15A__) || defined(__SAMD21G15B__) || defined(__SAMD21G15D__)
  #define SAMD21G
  #define SAMD21_FLASH_KB   32
#elif defined(__SAMD21G16A__) || defined(__SAMD21G16B__) || defined(__SAMD21G16D__)
  #define SAMD21G
  #define SAMD21_FLASH_KB   64
#elif defined(__SAMD21G17A__) || defined(__SAMD21G17AU__) || defined(__SAMD21G17D__)
  #define SAMD21G
  #define SAMD21_FLASH_KB   128
#elif defined(__SAMD21G18A__) || defined(__SAMD21G18AU__)
  #define SAMD21G
  #define SAMD21_FLASH_KB   256
#elif defined(__SAMD21J15A__) || defined(__SAMD21J15B__) || defined(__SAMD21J15D__)
  #define SAMD21J
  #define SAMD21_FLASH_KB   32
#elif defined(__SAMD21J16A__) || defined(__SAMD21J16B__) || defined(__SAMD21J16D__)
  #define SAMD21J
  #define SAMD21_FLASH_KB   64
#elif defined(__SAMD21J17A__) || defined(__SAMD21J17D__)
  #define SAMD21J
  #define SAMD21_FLASH_KB   128
#elif defined(__SAMD21J18A__)
  #define SAMD21J
  #define SAMD21_FLASH_KB   256
#else
  #define __SAMD21G18A__
  #define SAMD21G
  #define SAMD21_FLASH_KB   256
#endif

// Memory sizes
#define FLASH_SIZE      (SAMD21_FLASH_KB * 1024UL)                  // flash size in bytes
#define FLASH_NB_OF_PAGES (FLASH_SIZE / 64)                         // number of flash pages
#define HMCRAMC0_SIZE   (SAMD21_FLASH_KB * 128UL)                   // SRAM size in bytes

// Peripherals: SAMD21E has SERCOM0..3 and TC3..5, SAMD21G SERCOM0..5 and TC3..5,
// SAMD21J SERCOM0..5 and TC3..7 (the definitions below are for all variants)
#if defined(SAMD21E)
  #define SAMD21_SERCOMS    4
#else
  #define SAMD21_SERCOMS    6
#endif

// Clock values
#define OSC8M_VALUE     8000000U  // internal 8MHz RC oscillator in Hz
#define DFLL48M_VALUE  48000000U  // DFLL48M in Hz
#define OSC32K_VALUE      32768U  // internal 32.768kHz oscillator in Hz
#define OSCULP32K_VALUE   32768U  // internal ultra low-power 32.768kHz oscillator in Hz
#define XOSC32K_VALUE     32768U  // external 32.768kHz crystal in Hz

